import {parseCSV,inspect,cleanRows,serializeCSV} from './core.js';
const $=id=>document.getElementById(id);let original=[],current=[],valid=false;const number=new Intl.NumberFormat('ko');
const delimiter=()=>$('delimiter').value==='tab'?'\t':$('delimiter').value;
function invalidate(){valid=false;$('result').hidden=true;for(const k of ['row','column','duplicate','empty'])$(k+'-count').textContent='—';$('warnings').replaceChildren();$('status').classList.remove('error');$('status').textContent='입력이나 구분자가 바뀌었습니다. 다시 검사하세요.';}
function render(){
 if(!valid)return;current=cleanRows(original,{header:$('header').checked,trim:$('trim').checked,dedupe:$('dedupe').checked,empty:$('empty').checked});
 const summary=inspect(original,$('header').checked);for(const [id,key] of [['row','rows'],['column','columns'],['duplicate','duplicates'],['empty','empty']])$(id+'-count').textContent=number.format(summary[key]);
 const warnings=[];if(summary.irregular.length)warnings.push(`첫 행과 열 수가 다른 행 ${summary.irregular.length}개: ${summary.irregular.slice(0,12).join(', ')}${summary.irregular.length>12?' …':''}`);if(summary.duplicateHeaders)warnings.push(`같은 제목 ${summary.duplicateHeaders}개가 더 있습니다.`);if(summary.emptyHeaders)warnings.push(`비어 있는 제목 ${summary.emptyHeaders}개가 있습니다.`);
 $('warnings').replaceChildren(...warnings.map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));$('status').textContent=warnings.length?'읽기 완료. 아래 항목을 확인하세요.':'CSV 형식을 정상적으로 읽었습니다.';$('status').classList.remove('error');
 $('preview').replaceChildren();const tbody=document.createElement('tbody');current.slice(0,20).forEach((row,i)=>{const tr=document.createElement('tr');if(row.length!==current[0].length)tr.className='irregular';row.slice(0,12).forEach(value=>{const cell=document.createElement(i===0&&$('header').checked?'th':'td');cell.textContent=value.length>1000?value.slice(0,1000)+'…':value;if(cell.tagName==='TH')cell.scope='col';tr.append(cell);});tbody.append(tr);});$('preview').append(tbody);
 $('change-count').textContent=`전체 ${number.format(original.length)}행 → ${number.format(current.length)}행 (제목 포함)`;$('result').hidden=false;
}
$('input').addEventListener('input',invalidate);$('delimiter').addEventListener('change',invalidate);for(const key of ['header','trim','dedupe','empty'])$(key).addEventListener('change',render);
$('file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;invalidate();try{if(file.size>5*1024*1024)throw new Error('5MB 이하의 파일을 선택하세요.');const buffer=await file.arrayBuffer();let text;try{text=new TextDecoder('utf-8',{fatal:true}).decode(buffer);}catch{throw new Error('UTF-8 파일이 아닙니다. 원래 프로그램에서 UTF-8 CSV로 다시 저장하세요.');}$('input').value=text;$('filename').textContent=file.name;$('delimiter').value=file.name.toLowerCase().endsWith('.tsv')?'tab':',';$('status').textContent='파일을 읽었습니다. 구분자를 확인하고 검사하세요.';}catch(error){$('status').textContent=error.message;$('status').classList.add('error');}finally{$('file').value='';}});
$('sample').addEventListener('click',()=>{if($('input').value){$('status').textContent='원문이 있습니다. 원문을 비운 뒤 예시를 넣어주세요.';return;}$('input').value='상품,수량,메모\n사과,3,"오전, 문 앞"\n배,2,냉장 보관\n배,2,냉장 보관\n,,\n포도,1';$('delimiter').value=',';$('filename').textContent='예시 데이터';invalidate();});
$('analyze').addEventListener('click',()=>{try{if(new TextEncoder().encode($('input').value).length>5*1024*1024)throw new Error('5MB 이하의 텍스트를 입력하세요.');original=parseCSV($('input').value,delimiter());if(!original.length)throw new Error('먼저 CSV를 입력하거나 파일을 선택하세요.');valid=true;render();}catch(error){invalidate();$('status').textContent=error.message;$('status').classList.add('error');}});
function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
$('csv').addEventListener('click',()=>{if(valid)download(serializeCSV(current,{delimiter:',',safe:$('safe').checked}),'text/csv;charset=utf-8','정리한-데이터.csv');});
$('json').addEventListener('click',()=>{if(valid)download(JSON.stringify(current,null,2),'application/json;charset=utf-8','정리한-데이터.json');});
